-- Migração segura: acrescenta O Que é o Espiritismo (50 questões).
-- Preserva as questões existentes; atualiza ou insere as 50 questões (códigos 801 a 850).
BEGIN;

ALTER TABLE public.questions DROP CONSTRAINT IF EXISTS questions_book_check;
ALTER TABLE public.questions ADD CONSTRAINT questions_book_check
  CHECK (book IN ('livro_espiritos','evangelho','ceu_inferno','genese','livro_mediuns','obras_postumas','nosso_lar','os_mensageiros','o_que_e_espiritismo'));

ALTER TABLE public.questions DROP CONSTRAINT IF EXISTS questions_difficulty_check;
ALTER TABLE public.questions ADD CONSTRAINT questions_difficulty_check
  CHECK (difficulty IN ('facil','medio','dificil','expert'));

WITH incoming AS (
  SELECT * FROM jsonb_to_recordset($questions$[{"code":801,"book":"o_que_e_espiritismo","statement":"Segundo a biografia escrita por Henri Sausse em 'O Que é o Espiritismo', em que cidade e data nasceu Allan Kardec?","option_a":"Em Lyon, a 3 de outubro de 1804.","option_b":"Em Paris, a 18 de abril de 1804.","option_c":"Em Bordeaux, a 31 de março de 1805.","option_d":"Em Tours, a 3 de novembro de 1803.","option_e":"Em Genebra, a 15 de agosto de 1804.","correct_option":"A","explanation":"Henri Sausse registra que Allan Kardec nasceu em Lyon a 3 de outubro de 1804, recebendo o nome civil de Hippolyte Léon Denizard Rivail.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"facil","active":true},{"code":802,"book":"o_que_e_espiritismo","statement":"Qual era o nome civil completo do Codificador do Espiritismo antes de adotar o pseudônimo Allan Kardec?","option_a":"Jean-Baptiste Léon Fortier Rivail.","option_b":"Hippolyte Léon Denizard Rivail.","option_c":"Pierre-Paul Didier Baudin.","option_d":"Camille Nicolas Denizard Flammarion.","option_e":"Henri Léon Sausse Rivail.","correct_option":"B","explanation":"Filho do magistrado Jean-Baptiste Antoine Rivail, o Codificador chamava-se no registro civil Hippolyte Léon Denizard Rivail.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"facil","active":true},{"code":803,"book":"o_que_e_espiritismo","statement":"Com quem o professor Hippolyte Léon Denizard Rivail se casou em 6 de fevereiro de 1832?","option_a":"Com Caroline e Julie Baudin.","option_b":"Com Ruth Japhet.","option_c":"Com Amélie Gabrielle Boudet.","option_d":"Com Madame Plainemaison.","option_e":"Com Ermance Dufaux.","correct_option":"C","explanation":"Em 1832, o professor Rivail desposou Amélie Gabrielle Boudet, culta professora que foi sua dedicada companheira e colaboradora durante toda a vida.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"medio","active":true},{"code":804,"book":"o_que_e_espiritismo","statement":"Em que ano, segundo Henri Sausse, o professor Rivail ouviu falar pela primeira vez das mesas girantes por meio do magnetizador Sr. Fortier?","option_a":"Em 1850, durante um congresso de magnetismo em Lyon.","option_b":"Em 1852, na Academia Real de Ciências de Arras.","option_c":"Em 1857, pouco antes de publicar O Livro dos Espíritos.","option_d":"Em 1854, quando o Sr. Fortier lhe relatou que as mesas não apenas giravam, mas também falavam.","option_e":"Em 1848, logo após os fenômenos de Hydesville.","correct_option":"D","explanation":"Foi em 1854 que o Sr. Fortier, magnetizador de suas relações, falou-lhe pela primeira vez das mesas girantes e das comunicações obtidas por batidas.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"medio","active":true},{"code":805,"book":"o_que_e_espiritismo","statement":"Na casa de qual família o professor Rivail iniciou seus estudos regulares e metódicos das comunicações psicográficas por meio de duas jovens médiuns?","option_a":"Na casa da família Sausse, em Lyon.","option_b":"Na casa da família Delanne, em Paris.","option_c":"Na casa da família Lachâtre, em Toulon.","option_d":"Na casa da família Fortier.","option_e":"Na casa da família Baudin, com as jovens Caroline e Julie.","correct_option":"E","explanation":"Foi nas reuniões semanais na casa da família Baudin, onde escreviam na cesta-pião as jovens médiuns Srta. Julie e Srta. Caroline Baudin, que Rivail iniciou seus estudos sérios.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"medio","active":true},{"code":806,"book":"o_que_e_espiritismo","statement":"Por meio de qual médium sonâmbula o professor Rivail fez a verificação e revisão completa dos cinquenta cadernos que deram origem a 'O Livro dos Espíritos'?","option_a":"Srta. Ruth Japhet.","option_b":"Srta. Aline Carlotti.","option_c":"Sra. d'Espérance.","option_d":"Sra. Plainemaison.","option_e":"Sra. Amélie Boudet.","correct_option":"A","explanation":"Cerca de cinquenta cadernos confiados pelos Srs. Carlotti, René Taillandier, Tiedeman-Manthese e Sardou foram coordenados e revistos com o concurso da médium Srta. Japhet.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"dificil","active":true},{"code":807,"book":"o_que_e_espiritismo","statement":"Em que data veio a lume a primeira edição de 'O Livro dos Espíritos', marco inaugural da Codificação Espírita?","option_a":"31 de março de 1857.","option_b":"18 de abril de 1857.","option_c":"15 de agosto de 1859.","option_d":"1 de janeiro de 1858.","option_e":"3 de outubro de 1856.","correct_option":"B","explanation":"A primeira edição de O Livro dos Espíritos foi publicada em Paris, pela livraria Dentu, no Palais-Royal, em 18 de abril de 1857.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"facil","active":true},{"code":808,"book":"o_que_e_espiritismo","statement":"Por que o professor Rivail decidiu assinar as obras espíritas com o pseudônimo Allan Kardec?","option_a":"Por imposição da Academia Real de Ciências de Arras.","option_b":"Para homenagear seu antigo mestre suíço Pestalozzi.","option_c":"Para não confundir sua obra espírita, fruto do ensino dos Espíritos, com seus conhecidos livros pedagógicos assinados com o nome civil.","option_d":"Para ocultar sua nacionalidade francesa diante das autoridades eclesiásticas.","option_e":"Porque seu editor exigiu um nome de sonoridade inglesa para ampliar as vendas.","correct_option":"C","explanation":"Sendo seu nome civil muito conhecido pelas obras didáticas e gramaticais, adotou o nome Allan Kardec — que seu Espírito protetor revelou ter sido seu em existência anterior entre os druidas — para distinguir a obra espírita.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"dificil","active":true},{"code":809,"book":"o_que_e_espiritismo","statement":"Segundo o Preâmbulo de 'O Que é o Espiritismo', qual foi o objetivo principal de Allan Kardec ao publicar este livro sumário?","option_a":"Criar um ritual litúrgico obrigatório para todas as sociedades espíritas da França.","option_b":"Reunir apenas relatos de fenômenos físicos extraordinários para entreter o público.","option_c":"Combater pessoalmente os sacerdotes e cientistas que atacavam sua reputação.","option_d":"Oferecer um resumo sintético dos princípios da Doutrina e responder às principais objeções para quem deseja compreendê-la rapidamente.","option_e":"Substituir definitivamente a leitura de O Livro dos Espíritos e de O Livro dos Médiuns.","correct_option":"D","explanation":"No Preâmbulo, Kardec explica que publicou este resumo para dar em poucas palavras uma ideia exata do Espiritismo, fornecendo os pontos cardeais da ciência e respondendo às objeções mais comuns.","reference":"O Que é o Espiritismo - Preâmbulo","difficulty":"medio","active":true},{"code":810,"book":"o_que_e_espiritismo","statement":"No Capítulo I de 'O Que é o Espiritismo' ('Pequena conferência espírita'), quais são os três interlocutores com quem o Adeptos dialoga sucessivamente?","option_a":"O Médico, o Juiz e o Filósofo.","option_b":"O Materialista, o Cientista e o Pastor.","option_c":"O Jornalista, o Magnetizador e o Bispo.","option_d":"O Professor, o Ateo e o Monge.","option_e":"O Crítico, o Cético e o Padre.","correct_option":"E","explanation":"O Capítulo I é dividido em três diálogos: o Primeiro Diálogo com O Crítico, o Segundo Diálogo com O Cético e o Terceiro Diálogo com O Padre.","reference":"O Que é o Espiritismo - Cap. I, Pequena conferência espírita","difficulty":"facil","active":true},{"code":811,"book":"o_que_e_espiritismo","statement":"No Primeiro Diálogo ('O Crítico'), que diferença fundamental o Visitante aponta entre a atitude do Crítico e a do Cético?","option_a":"O Cético duvida, mas busca esclarecer-se; o Crítico julga sem conhecer e procura ridicularizar aquilo que não estudou.","option_b":"O Crítico realiza experiências práticas, enquanto o Cético apenas escreve panfletos.","option_c":"O Cético é sempre inimigo da Ciência, ao passo que o Crítico defende as academias.","option_d":"Não há diferença alguma, pois ambos negam a existência de Deus.","option_e":"O Crítico crê nos Espíritos, enquanto o Cético acredita apenas em anjos.","correct_option":"A","explanation":"Kardec mostra no diálogo que o Crítico condena a priori e usa a zombaria sem haver lido nem observado nada, ao passo que o Cético sincero apresenta dúvidas racionais e deseja instruir-se.","reference":"O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico","difficulty":"medio","active":true},{"code":812,"book":"o_que_e_espiritismo","statement":"Ao responder ao Crítico sobre os casos de charlatanismo e exploração financeira das manifestações, qual é a posição firme da Doutrina Espírita?","option_a":"Reconhece que apenas os fenômenos de efeitos físicos podem ser remunerados.","option_b":"Repudia formalmente qualquer exploração mercantil da mediunidade, declarando que o verdadeiro Espiritismo jamais faz de suas manifestações objeto de lucro.","option_c":"Tolera a cobrança moderada quando o médium é comprovadamente pobre.","option_d":"Permite sessões pagas desde que a renda seja destinada a hospitais.","option_e":"Autoriza os médiuns profissionais a cobrarem consultas particulares.","correct_option":"B","explanation":"Kardec enfatiza que o Espiritismo sério condena de modo absoluto os espetáculos pagos e o comércio da mediunidade, não podendo a Ciência verdadeira responder pelos abusos dos charlatães.","reference":"O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico","difficulty":"dificil","active":true},{"code":813,"book":"o_que_e_espiritismo","statement":"No início do Segundo Diálogo ('O Cético'), como o espírita recebe a declaração do Visitante de que não crê nos Espíritos, mas deseja compreender a questão?","option_a":"Cobrando uma taxa de matrícula no curso preparatório da Sociedade.","option_b":"Aconselhando-o a desistir, pois a fé espírita só se obtém por graça mística.","option_c":"Com simpatia e respeito, pois a dúvida sincera de quem procura instruir-se merece explicação racional.","option_d":"Com indignação, recusando-se a conversar com quem ainda não tem fé.","option_e":"Exigindo que o visitante faça antes um juramento de adesão religiosa.","correct_option":"C","explanation":"Kardec acolhe o Cético com estima, esclarecendo que o Espiritismo não exige fé cega, mas convida ao exame sério, metódico e livre de ideias preconcebidas.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"facil","active":true},{"code":814,"book":"o_que_e_espiritismo","statement":"Para demonstrar ao Cético a existência da alma independente da matéria, que argumento fundamental o espírita utiliza?","option_a":"O cálculo matemático da distância entre as estrelas fixas.","option_b":"A tradição mitológica dos povos gregos e romanos.","option_c":"A autoridade infalível dos concílios medievais.","option_d":"O fato de que o pensamento, a vontade e o livre-arbítrio são propriedades inteligentes que não podem ser produzidas pela matéria bruta.","option_e":"A semelhança anatômica entre o sistema nervoso humano e o dos vegetais.","correct_option":"D","explanation":"Todo efeito inteligente há de ter uma causa inteligente; como a matéria por si mesma é inerte e desprovida de inteligência, o pensamento humano prova a presença de um princípio espiritual.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"expert","active":true},{"code":815,"book":"o_que_e_espiritismo","statement":"Segundo explica Kardec ao Cético, de quantos elementos essenciais se compõe o homem encarnado?","option_a":"De cinco corpos astrais independentes entre si.","option_b":"De dois elementos apenas: o corpo carnal e o fluido elétrico.","option_c":"De quatro elementos: terra, água, ar e fogo.","option_d":"De um único elemento material capaz de produzir o pensamento.","option_e":"De três elementos: o corpo (ser material), a alma (Espírito encarnado) e o perispírito (envoltório semimaterial que une a alma ao corpo).","correct_option":"E","explanation":"Kardec apresenta a constituição ternária do homem: 1º o corpo físico; 2º a alma ou Espírito; 3º o perispírito, laço fluídico semimaterial que serve de intermediário entre ambos.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"facil","active":true},{"code":816,"book":"o_que_e_espiritismo","statement":"Quando o Cético pergunta por que uma mesa se move ou responde por pancadas nas sessões de efeitos físicos, o que o espírita lhe esclarece?","option_a":"Que a mesa é apenas um instrumento passivo movido pelo Espírito, que combina parte de seu perispírito com o fluido animalizado do médium.","option_b":"Que a madeira adquire inteligência própria ao ser magnetizada pelos presentes.","option_c":"Que o movimento resulta exclusivamente da eletricidade terrestre acumulada no móvel.","option_d":"Que todos os movimentos de mesas são produzidos por mecanismos ocultos sob o soalho.","option_e":"Que os Espíritos se transformam materialmente na própria estrutura da mesa.","correct_option":"A","explanation":"A mesa não pensa nem tem músculos: o Espírito utiliza o fluido próprio do médium combinado ao fluido universal e ao seu perispírito para imprimir movimento ao objeto e dar sinais convencionados.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"medio","active":true},{"code":817,"book":"o_que_e_espiritismo","statement":"No diálogo com o Cético, qual é a posição do Espiritismo a respeito do Magnetismo e do Sonambulismo?","option_a":"Considera o magnetismo uma superstição medieval sem qualquer base real.","option_b":"Reconhece-os como ciências irmãs que prepararam o caminho ao demonstrar a ação dos fluidos e a independência da alma.","option_c":"Afirma que o magnetizador só cura quando pronuncia fórmulas cabalísticas.","option_d":"Sustenta que todo médium psicógrafo precisa antes ser magnetizado por um médico.","option_e":"Declara que o fluido magnético destrói a faculdade mediúnica.","correct_option":"B","explanation":"Kardec explica que o magnetismo preparou o caminho do Espiritismo, pois o estudo do fluido magnético e da clarividência sonambúlica já demonstrava a ação da alma fora dos sentidos corpóreos.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"dificil","active":true},{"code":818,"book":"o_que_e_espiritismo","statement":"Que fatos comprovam ao Cético que as comunicações mediúnicas não são simples reflexo das ideias do próprio médium?","option_a":"O fato de o médium usar sempre papel timbrado das sociedades espíritas.","option_b":"A velocidade com que o lápis percorre o papel em linha reta.","option_c":"Comunicações contrárias às opiniões e conhecimentos do médium, em línguas que ele ignora ou até por pessoas analfabetas.","option_d":"O cansaço muscular sentido no braço após duas horas de escrita.","option_e":"A presença obrigatória de sete testemunhas diplomadas na sala.","correct_option":"C","explanation":"O Espírito frequentemente trata de assuntos estranhos aos estudos do médium, contradiz suas ideias preconcebidas, revela fatos desconhecidos e por vezes escreve em idiomas que o médium desconhece.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"dificil","active":true},{"code":819,"book":"o_que_e_espiritismo","statement":"Por que os Espíritos não vêm revelar tesouros ocultos, fórmulas para enriquecer sem trabalho ou invenções prontas para especulação financeira?","option_a":"Porque estão proibidos de observar a superfície material da Terra.","option_b":"Porque apenas os Espíritos zombeteiros conhecem onde estão os tesouros.","option_c":"Porque perderam toda a capacidade de raciocínio prático ao desencarnar.","option_d":"Porque a lei de Deus impõe ao homem o progresso pelo trabalho e pela pesquisa própria, e os bons Espíritos não servem à cupidez nem ao orgulho.","option_e":"Porque desconhecem o valor das moedas modernas.","correct_option":"D","explanation":"Os Espíritos Superiores auxiliam o progresso moral e intelectual da humanidade, mas não poupam ao homem o esforço do trabalho; quem busca os Espíritos por interesse material torna-se joguete de mistificadores.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"expert","active":true},{"code":820,"book":"o_que_e_espiritismo","statement":"No diálogo com o Cético, por que os fenômenos espíritas não podem ser repetidos à vontade, como uma experiência física ou química de laboratório?","option_a":"Porque os médiuns perdem suas faculdades diante de mais de três pessoas.","option_b":"Porque a gravidade terrestre anula o perispírito durante o dia.","option_c":"Porque as leis civis proíbem experiências científicas com médiuns.","option_d":"Porque os fluidos espirituais evaporam na presença de luz solar.","option_e":"Porque os Espíritos são seres livres e inteligentes, e não máquinas nem reagentes químicos submetidos ao capricho dos observadores.","correct_option":"E","explanation":"As ciências físicas operam sobre a matéria inerte que se manipula à vontade; o Espiritismo lida com inteligências livres que têm vontade própria e não se prestam a exigências frívolas de curiosos.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"expert","active":true},{"code":821,"book":"o_que_e_espiritismo","statement":"No Segundo Diálogo, como o espírita explica ao Cético a justiça das desigualdades de aptidões intelectuais e morais que as crianças trazem desde o berço?","option_a":"Pela preexistência da alma e pela pluralidade das existências (reencarnação), em que cada Espírito traz o patrimônio adquirido em vidas anteriores.","option_b":"Pela transmissão hereditária da própria alma dos pais para os filhos.","option_c":"Pelo acaso genético resultante apenas da alimentação materna.","option_d":"Pelo privilégio arbitrário concedido por Deus a certas almas recém-criadas.","option_e":"Pela influência astrológica da posição dos planetas no instante do parto.","correct_option":"A","explanation":"Se Deus criasse almas novas a cada nascimento com aptidões tão desiguais, seria parcial; a reencarnação explica que uns já viveram e progrediram mais do que outros em existências precedentes.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"dificil","active":true},{"code":822,"book":"o_que_e_espiritismo","statement":"Quando o Cético pergunta se o Espírito pode retrogradar e reencarnar no corpo de um animal, o que responde a Doutrina Espírita?","option_a":"Apenas nas espécies domésticas mais próximas do convívio humano.","option_b":"Não; o progresso do Espírito é contínuo: ele pode estacionar, mas jamais retrograda, sendo a metempsicose nos animais contrária à lei divina.","option_c":"Sim, como punição temporária para os grandes criminosos da humanidade.","option_d":"Sim, sempre que o homem se entrega aos instintos puramente sensuais.","option_e":"Depende da decisão dos Espíritos Superiores em cada julgamento.","correct_option":"B","explanation":"Kardec distingue claramente a reencarnação espírita da antiga metempsicose: o Espírito humano nunca volta a ser animal; se estaciona, reencarna em condições humanas de expiação para avançar.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"expert","active":true},{"code":823,"book":"o_que_e_espiritismo","statement":"No Terceiro Diálogo ('O Padre'), como o espírita responde à afirmação eclesiástica de que apenas o demônio e seus anjos decaídos podem comunicar-se com os homens?","option_a":"Concordando que as almas humanas permanecem adormecidas até o juízo final.","option_b":"Afirmando que os maus Espíritos não existem no plano espiritual.","option_c":"Mostrando que seria absurdo e contrário à bondade de Deus conceder liberdade de ação apenas ao espírito do mal e proibir as boas almas de consolar e instruir os vivos.","option_d":"Dizendo que os Espíritos só se comunicam dentro dos templos consagrados.","option_e":"Alegando que o Antigo e o Novo Testamento jamais mencionam manifestações espirituais.","correct_option":"C","explanation":"Kardec argumenta com lógica irrefutável: se Deus permite que os maus Espíritos tentem os homens, com muito mais razão permite que os bons Espíritos venham ampará-los e encaminhá-los ao bem.","reference":"O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre","difficulty":"medio","active":true},{"code":824,"book":"o_que_e_espiritismo","statement":"No Terceiro Diálogo com o Padre, qual é o critério seguro apontado pelo Espiritismo para distinguir se um Espírito comunicante é bom ou mau?","option_a":"O nome famoso ou sagrado com que ele assina a mensagem.","option_b":"A beleza caligráfica da escrita psicografada pelo médium.","option_c":"A intensidade das pancadas ou o peso da mesa que se levanta.","option_d":"A qualidade moral de sua linguagem e de seus conselhos, pois 'reconhece-se a árvore pelo fruto': um Espírito que só ensina a caridade e o bem não pode ser mau.","option_e":"O horário noturno ou diurno em que ocorre a reunião mediúnica.","correct_option":"D","explanation":"Aplicando a máxima de Jesus ('Pelos seus frutos os conhecereis'), Kardec lembra que o demônio não poderia pregar o amor a Deus, o perdão das ofensas, a humildade e a caridade sem destruir seu próprio reino.","reference":"O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre","difficulty":"facil","active":true},{"code":825,"book":"o_que_e_espiritismo","statement":"Quando o Padre cita a proibição mosaica de interrogar os mortos (Deuteronômio), que explicação histórica e doutrinária o espírita apresenta?","option_a":"Que Moisés desconhecia totalmente a existência da alma imortal.","option_b":"Que o texto bíblico foi inventado apenas no século XVIII.","option_c":"Que Moisés proibiu apenas a escrita manual, mas permitiu as mesas girantes.","option_d":"Que a lei mosaica só se aplicava aos sacerdotes egípcios e babilônios.","option_e":"Que Moisés reprimiu o abuso supersticioso da adivinhação mercenária e idólatra entre os hebreus, e que essa própria proibição prova que a comunicação com os mortos era real.","correct_option":"E","explanation":"Não se proíbe aquilo que não existe: Moisés vetou a evocação transformada em ofício de adivinhação e comércio supersticioso, ao passo que o Espiritismo condena esses mesmos abusos e busca a edificação moral.","reference":"O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre","difficulty":"expert","active":true},{"code":826,"book":"o_que_e_espiritismo","statement":"No diálogo com o Padre, qual é o ponto em que a Doutrina Espírita diverge do dogma teológico das penas eternas e de um inferno material de fogo?","option_a":"Os Espíritos ensinam que as penas são morais e proporcionais às faltas, mas nunca perpétuas, pois Deus jamais fecha ao arrependimento a porta da regeneração.","option_b":"A Doutrina Espírita afirma que o sofrimento dura exatamente sete anos para todos os Espíritos.","option_c":"O Espiritismo ensina que os Espíritos criminosos são aniquilados no momento do desencarne.","option_d":"Kardec sustenta que apenas as preces pagas podem libertar uma alma sofredora.","option_e":"O Espiritismo nega que o culpado sofra qualquer consequência após a morte.","correct_option":"A","explanation":"A condenação irrevogável e eterna é incompatível com a infinita justiça e bondade de Deus; o Espírito culpado sofre nas trevas morais de sua consciência até arrepender-se e reparar o mal por novas provas.","reference":"O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre","difficulty":"expert","active":true},{"code":827,"book":"o_que_e_espiritismo","statement":"Segundo o Capítulo II ('Noções elementares de Espiritismo', itens 1 a 8), qual é a grande missão prática do Espiritismo perante o mundo moderno?","option_a":"Formar uma corporação política para governar as nações.","option_b":"Combater a incredulidade e o materialismo pela prova dos fatos e regenerar a humanidade pela aplicação da moral evangélica.","option_c":"Ensinar processos mágicos para evitar as doenças do corpo físico.","option_d":"Descobrir minas de ouro e pedras preciosas por meio de sonâmbulos.","option_e":"Substituir as ciências exatas por revelações místicas.","correct_option":"B","explanation":"Nos itens iniciais do Capítulo II, Kardec destaca que o Espiritismo é o mais poderoso antagonista do materialismo e tem por fim o melhoramento moral da humanidade.","reference":"O Que é o Espiritismo - Cap. II, itens 1 a 8","difficulty":"facil","active":true},{"code":828,"book":"o_que_e_espiritismo","statement":"No Capítulo II (itens 17 a 23), ao tratar das diversas ordens de Espíritos, como Allan Kardec sintetiza as três categorias principais da escala espírita?","option_a":"Visíveis, Invisíveis e Tangíveis.","option_b":"Antigos, Medievais e Modernos.","option_c":"Espíritos imperfeitos (predomínio da matéria sobre o espírito), bons Espíritos (predomínio do espírito sobre a matéria, desejo do bem) e Espíritos puros (perfeição absoluta).","option_d":"Querubins, Serafins e Arcanjos.","option_e":"Sábios, Guerreiros e Artistas.","correct_option":"C","explanation":"Embora a transição entre os graus seja insensível, Kardec resume a classificação em Espíritos imperfeitos (inclinados ao mal ou levianos), bons Espíritos e Espíritos puros ou superiores.","reference":"O Que é o Espiritismo - Cap. II, itens 17 a 23","difficulty":"facil","active":true},{"code":829,"book":"o_que_e_espiritismo","statement":"Segundo o Capítulo II (itens 21 e 22), que tipos de Espíritos compõem a classe dos chamados Espíritos levianos, zombeteiros e pseudossábios?","option_a":"Almas de crianças desencarnadas que jamais atingirão a maturidade intelectual.","option_b":"Entidades não humanas criadas exclusivamente para habitar as florestas.","option_c":"Espíritos superiores encarregados de punir os cientistas orgulhosos.","option_d":"Espíritos imperfeitos que, sem serem essencialmente maus, comprazem-se em mistificar, intrigar ou ostentar falso saber com linguagem pomposa.","option_e":"Espíritos puros que testam a paciência dos médiuns por meio de mentiras.","correct_option":"D","explanation":"Nos itens 21 e 22, Kardec descreve os Espíritos levianos, ignorantes e zombeteiros, que se intrometem em tudo e respondem sem saber, bem como os pseudossábios, cheios de orgulho e sistemas falsos.","reference":"O Que é o Espiritismo - Cap. II, itens 21 e 22","difficulty":"expert","active":true},{"code":830,"book":"o_que_e_espiritismo","statement":"Conforme o Capítulo II (itens 25 a 29), qual é a diferença entre manifestações ocultas e manifestações ostensivas dos Espíritos?","option_a":"As ocultas são sempre produzidas por maus Espíritos e as ostensivas apenas por anjos.","option_b":"As ocultas exigem aparelhos elétricos e as ostensivas dispensam médiuns.","option_c":"Não existe diferença real entre ambas na classificação de Allan Kardec.","option_d":"As ocultas ocorrem apenas à meia-noite e as ostensivas ao meio-dia.","option_e":"As ocultas dão-se pela inspiração invisível no pensamento (sugestões da consciência), enquanto as ostensivas produzem-se por efeitos apreciáveis aos sentidos ou pela mediunidade.","correct_option":"E","explanation":"A ação oculta ocorre quando os Espíritos nos inspiram pensamentos e conselhos sem que o percebamos; a ação ostensiva ou patente se dá pela escrita, fala, visão, audição ou fenômenos físicos.","reference":"O Que é o Espiritismo - Cap. II, itens 25 a 29","difficulty":"facil","active":true},{"code":831,"book":"o_que_e_espiritismo","statement":"De acordo com o Capítulo II (itens 30 a 35), que são as manifestações espontâneas e as manifestações provocadas?","option_a":"Espontâneas ocorrem sem que ninguém chame o Espírito; provocadas dão-se por meio da evocação ou do concurso intencional dos médiuns.","option_b":"Espontâneas acontecem apenas no sono; provocadas acontecem em vigília.","option_c":"Espontâneas são exclusivas das crianças; provocadas pertencem aos idosos.","option_d":"Espontâneas são as obtidas por médiuns pagos; provocadas são as gratuitas.","option_e":"Espontâneas são as escritas em verso; provocadas são as escritas em prosa.","correct_option":"A","explanation":"Kardec explica que muitas vezes os Espíritos se manifestam espontaneamente (por ruídos, aparições ou comunicações não solicitadas), mas também podem ser chamados por evocação.","reference":"O Que é o Espiritismo - Cap. II, itens 30 a 35","difficulty":"medio","active":true},{"code":832,"book":"o_que_e_espiritismo","statement":"No Capítulo II (itens 40 a 47), como são denominados no Espiritismo os médiuns que escrevem sob a influência dos Espíritos?","option_a":"Médiuns de efeitos físicos.","option_b":"Médiuns escreventes ou psicógrafos.","option_c":"Médiuns tiptólogos.","option_d":"Médiuns videntes.","option_e":"Médiuns audientes.","correct_option":"B","explanation":"No item 45, Allan Kardec define os médiuns escreventes ou psicógrafos como aqueles que têm a faculdade de escrever por si mesmos sob a influência dos Espíritos.","reference":"O Que é o Espiritismo - Cap. II, item 45","difficulty":"facil","active":true},{"code":833,"book":"o_que_e_espiritismo","statement":"Segundo o Capítulo II (itens 46 a 49), qual é a diferença entre os médiuns psicógrafos mecânicos, semimecânicos e intuitivos?","option_a":"O mecânico escreve dormindo; o intuitivo escreve em transe cataléptico.","option_b":"Não há distinção alguma entre os três modos de psicografia.","option_c":"No mecânico a mão move-se sem consciência do que escreve; no intuitivo o Espírito atua sobre o pensamento do médium; no semimecânico há impulso na mão acompanhado de consciência das palavras.","option_d":"O mecânico usa máquinas de escrever; o intuitivo usa cestas; o semimecânico usa ardósias.","option_e":"O mecânico só recebe Espíritos inferiores; o intuitivo só recebe Espíritos puros.","correct_option":"C","explanation":"No médium mecânico o Espírito move diretamente a mão sem que o médium tenha consciência do escrito; no intuitivo transmite o pensamento; no semimecânico participam ambos os mecanismos.","reference":"O Que é o Espiritismo - Cap. II, itens 46 a 49","difficulty":"expert","active":true},{"code":834,"book":"o_que_e_espiritismo","statement":"No Capítulo II (item 44), que nome específico Allan Kardec dá à faculdade raríssima de obter a escrita direta traçada pelos próprios Espíritos sem o uso da mão do médium?","option_a":"Bicorporeidade tangível.","option_b":"Tiptologia alfabética.","option_c":"Psicofonia consciente.","option_d":"Pneumatografia (e pneumatofonia para os sons articulados no ar).","option_e":"Clariaudiência intuitiva.","correct_option":"D","explanation":"Kardec denomina pneumatografia a escrita direta produzida pelos Espíritos sem intermediário manual, advertindo também contra as fraudes dos que simulam esse fenômeno.","reference":"O Que é o Espiritismo - Cap. II, item 44","difficulty":"dificil","active":true},{"code":835,"book":"o_que_e_espiritismo","statement":"Segundo o Capítulo II ('Escolhos da mediunidade', itens 55 a 64), qual é o maior perigo que ameaça os médiuns e pode levá-los à obsessão e à perda da assistência dos bons Espíritos?","option_a":"A leitura comparada das comunicações em grupos sérios.","option_b":"O estudo constante das obras fundamentais da Codificação.","option_c":"A prática gratuita da caridade em benefício dos enfermos.","option_d":"O hábito de fazer preces antes das reuniões mediúnicas.","option_e":"O orgulho, a presunção de infalibilidade e a fascinação exercida por Espíritos enganadores que lisonjeiam a vaidade do médium.","correct_option":"E","explanation":"O orgulho é a pedra de toque: quando o médium se julga privilegiado e infalível, afasta os bons Espíritos e entrega-se aos Espíritos mistificadores e fascinadores.","reference":"O Que é o Espiritismo - Cap. II, itens 55 a 64","difficulty":"expert","active":true},{"code":836,"book":"o_que_e_espiritismo","statement":"De acordo com o Capítulo II ('Qualidades dos médiuns', itens 65 a 71), o que atrai os bons Espíritos para junto de um médium?","option_a":"As qualidades morais do médium: bondade, benevolência, simplicidade de coração, humildade, devotamento e amor ao bem.","option_b":"A riqueza material e os títulos acadêmicos do médium.","option_c":"A força física muscular e o temperamento sanguíneo.","option_d":"O uso de talismãs, vestes especiais e incensos.","option_e":"A cobrança de honorários elevados pelas sessões.","correct_option":"A","explanation":"A faculdade mediúnica em si é orgânica e independe da moral, mas o seu bom uso e a assistência dos bons Espíritos dependem essencialmente das qualidades morais do médium.","reference":"O Que é o Espiritismo - Cap. II, itens 65 a 71","difficulty":"facil","active":true},{"code":837,"book":"o_que_e_espiritismo","statement":"No Capítulo II ('Contradições', itens 90 a 97), qual é a causa principal das aparentes contradições encontradas em certas comunicações espíritas?","option_a":"A instabilidade do fluido cósmico universal durante os eclipses.","option_b":"A diversidade de graus de saber e moralidade entre os Espíritos comunicantes, pois cada um fala segundo seus conhecimentos e opiniões pessoais.","option_c":"A falta de dicionários padronizados nas escolas europeias.","option_d":"O defeito de fabricação dos lápis utilizados nas sessões.","option_e":"A variação climática entre os hemisférios norte e sul.","correct_option":"B","explanation":"Nem todos os Espíritos sabem tudo: os Espíritos inferiores ou pseudossábios emitem sistemas pessoais e opiniões divergentes, ao passo que os Espíritos Superiores estão sempre de acordo quanto ao ensino moral e fundamental.","reference":"O Que é o Espiritismo - Cap. II, itens 90 a 97","difficulty":"dificil","active":true},{"code":838,"book":"o_que_e_espiritismo","statement":"No início do Capítulo III ('Solução de alguns problemas pela Doutrina Espírita', item 105), o que ensina o Espiritismo sobre a pluralidade dos mundos?","option_a":"Que os demais planetas só serão habitados após a destruição da Terra.","option_b":"Que a vida espiritual não pode existir fora da atmosfera terrestre.","option_c":"Que todos os globos que circulam no espaço são habitados por seres apropriados à constituição física de cada mundo.","option_d":"Que apenas a Terra e Marte possuem seres vivos inteligentes.","option_e":"Que os astros são apenas pontos luminosos criados para enfeitar a noite terrestre.","correct_option":"C","explanation":"No item 105, Kardec expõe que todos os mundos que gravitam no espaço são habitados e apresentam diferentes graus de adiantamento físico e moral.","reference":"O Que é o Espiritismo - Cap. III, item 105","difficulty":"facil","active":true},{"code":839,"book":"o_que_e_espiritismo","statement":"Segundo o Capítulo III (itens 106 e 107), qual é a posição da Terra na hierarquia dos mundos habitados?","option_a":"É o único globo onde existe o livre-arbítrio humano.","option_b":"É um planeta superior a Júpiter em evolução moral e física.","option_c":"É o mundo mais atrasado e primitivo de todo o universo.","option_d":"Não está na primeira nem na última linha, mas é um dos mundos menos adiantados, onde ainda predominam as provas, expiações e necessidades materiais.","option_e":"É um mundo celeste onde só habitam Espíritos puros.","correct_option":"D","explanation":"Kardec esclarece que a Terra não ocupa nem o primeiro nem o último degrau, mas pertence à categoria dos mundos onde a imperfeição moral e as vicissitudes corporais ainda exigem duro trabalho e expiação.","reference":"O Que é o Espiritismo - Cap. III, itens 106 e 107","difficulty":"expert","active":true},{"code":840,"book":"o_que_e_espiritismo","statement":"De acordo com o Capítulo III ('Do homem durante a vida terrestre', itens 108 a 111), em que momento se completa a união definitiva da alma com o corpo?","option_a":"Somente quando o jovem atinge a maioridade civil.","option_b":"Apenas no momento da desencarnação do corpo físico.","option_c":"Apenas aos sete anos de idade, quando começa a razão.","option_d":"Três meses após o batismo religioso da criança.","option_e":"Começa na concepção e só é completa no instante do nascimento.","correct_option":"E","explanation":"No item 110, Kardec precisa que a união da alma com o corpo começa na concepção, mas só se torna completa no momento do nascimento.","reference":"O Que é o Espiritismo - Cap. III, item 110","difficulty":"medio","active":true},{"code":841,"book":"o_que_e_espiritismo","statement":"Segundo o Capítulo III (itens 112 e 113), o que ocorre com a alma durante o sono do corpo físico?","option_a":"Os laços que a prendem ao corpo afrouxam-se e a alma recobra parte de sua liberdade, entrando em relação com outros Espíritos nos sonhos.","option_b":"A alma permanece aprisionada exclusivamente dentro do coração.","option_c":"A alma adormece profundamente e perde toda a atividade consciente.","option_d":"O perispírito dissolve-se temporariamente até o despertar matinal.","option_e":"O Espírito desencarna definitivamente e outro Espírito ocupa o corpo.","correct_option":"A","explanation":"Enquanto o corpo repousa, o Espírito não precisa de descanso: afrouxam-se os laços fluídicos, ele percorre o espaço e comunica-se com encarnados e desencarnados, originando muitas lembranças de sonhos.","reference":"O Que é o Espiritismo - Cap. III, itens 112 e 113","difficulty":"medio","active":true},{"code":842,"book":"o_que_e_espiritismo","statement":"Segundo o Capítulo III (itens 116 a 119), o que faz o Espírito quando abusa de seu livre-arbítrio e retarda seu adiantamento?","option_a":"Recebe o perdão automático no instante da morte sem precisar progredir.","option_b":"Sofre as consequências de suas faltas e precisa recomeçar em novas existências corporais a tarefa que desempenhou mal.","option_c":"É condenado ao fogo eterno sem possibilidade de reparação.","option_d":"Regressa à condição de mineral ou vegetal.","option_e":"Perde a individualidade e dissolve-se no fluido cósmico.","correct_option":"B","explanation":"Não podendo ir para os mundos felizes sem haver-se depurado, o Espírito estacionário ou culpado reencarna em mundos de provas e expiações para reparar o tempo perdido.","reference":"O Que é o Espiritismo - Cap. III, itens 116 a 119","difficulty":"medio","active":true},{"code":843,"book":"o_que_e_espiritismo","statement":"Segundo o Capítulo III (itens 124 a 127), de que depende a duração e a intensidade da perturbação que se segue à morte?","option_a":"Da riqueza do mausoléu construído pela família na Terra.","option_b":"Da idade cronológica do corpo físico no instante do óbito.","option_c":"Da elevação moral do Espírito e do seu grau de desapego das coisas materiais.","option_d":"Da estação do ano e da fase da Lua no dia do desencarne.","option_e":"Do número de velas acesas ao redor do féretro.","correct_option":"C","explanation":"Para o homem de consciência pura, que já se desligou dos interesses terrenos durante a vida, o despertar espiritual é rápido e calmo; para o materialista e o culpado, a perturbação é longa e penosa.","reference":"O Que é o Espiritismo - Cap. III, itens 124 a 127","difficulty":"expert","active":true},{"code":844,"book":"o_que_e_espiritismo","statement":"De acordo com o Capítulo III (itens 129 e 130), todos os Espíritos desencarnados permanecem errantes indefinidamente?","option_a":"Sim, pois nenhum Espírito jamais fica livre da reencarnação.","option_b":"Não, porque após três séculos os Espíritos deixam de existir.","option_c":"Apenas os Espíritos inferiores deixam de ser errantes.","option_d":"Não; os Espíritos puros, que atingiram a perfeição e não precisam mais de novas reencarnações, não são mais errantes, pois seu estado é definitivo.","option_e":"Sim, todos os Espíritos continuam errantes por toda a eternidade.","correct_option":"D","explanation":"O estado errante é transitório e próprio dos Espíritos que ainda têm de reencarnar para progredir; os Espíritos puros já chegaram ao termo da escala e gozam da felicidade definitiva.","reference":"O Que é o Espiritismo - Cap. III, itens 129 e 130","difficulty":"medio","active":true},{"code":845,"book":"o_que_e_espiritismo","statement":"Segundo o Capítulo III ('Penas e gozos futuros', itens 133 a 137), qual é a natureza das penas e das alegrias da alma na vida espiritual?","option_a":"Consistem em torturas físicas produzidas por caldeiras e chamas materiais.","option_b":"Resumem-se na contemplação imóvel e ociosa sem qualquer atividade útil.","option_c":"Dependem exclusivamente da posição social que o indivíduo ocupou na Terra.","option_d":"São iguais para todos os Espíritos, independentemente de suas obras.","option_e":"São essencialmente morais e inerentes ao grau de elevação ou de imperfeição do próprio Espírito, que carrega em si mesmo o seu céu ou o seu inferno.","correct_option":"E","explanation":"Não tendo mais corpo carnal, o Espírito não sofre torturas físicas exteriores: a felicidade nasce da pureza, do amor e das missões úteis, enquanto o sofrimento decorre do remorso, das paixões não saciadas e da visão de suas vítimas.","reference":"O Que é o Espiritismo - Cap. III, itens 133 a 137","difficulty":"dificil","active":true},{"code":846,"book":"o_que_e_espiritismo","statement":"Conforme o Capítulo III (item 136), onde estão localizados o céu e o inferno segundo a Doutrina Espírita?","option_a":"Em toda parte: o céu está onde há Espíritos felizes e mundos superiores; o inferno está no próprio íntimo dos Espíritos imperfeitos e nos mundos de expiação.","option_b":"O céu localiza-se no Sol e o inferno na superfície da Lua.","option_c":"Ambos são lugares circunscritos cercados por muralhas intransponíveis.","option_d":"Existem apenas como figuras poéticas sem correspondência com o estado da alma.","option_e":"O céu fica acima das estrelas fixas e o inferno no centro incandescente da Terra.","correct_option":"A","explanation":"O céu e o inferno não são lugares geograficamente circunscritos: o Espírito feliz leva consigo a ventura onde quer que esteja, e o Espírito perverso ou impenitente carrega em si mesmo o seu tormento.","reference":"O Que é o Espiritismo - Cap. III, item 136","difficulty":"medio","active":true},{"code":847,"book":"o_que_e_espiritismo","statement":"Segundo o Capítulo III ('Causas anteriores das aflições', itens 144 a 148), onde reside a causa da maioria das aflições terrenas?","option_a":"No capricho arbitrário da Providência ao distribuir dores sem motivo.","option_b":"Na própria conduta imprudente, orgulhosa ou egoísta do homem na vida presente; e, quando não têm causa atual, nas faltas cometidas em existências anteriores.","option_c":"Na fatalidade cega do destino contra a qual o homem nada pode fazer.","option_d":"No pecado original cometido por um único casal no início dos tempos.","option_e":"Na influência maléfica dos cometas sobre a atmosfera terrestre.","correct_option":"B","explanation":"Kardec distingue duas fontes de aflições: 1ª as que o homem cria nesta própria vida por sua imprevidência e más paixões; 2ª as que atingem o homem de bem sem causa atual aparente, que são expiações de vidas passadas.","reference":"O Que é o Espiritismo - Cap. III, itens 144 a 148","difficulty":"expert","active":true},{"code":848,"book":"o_que_e_espiritismo","statement":"No Capítulo III (itens 146 a 148), por que a justiça divina exige que a falta cometida em uma existência seja reparada por uma expiação equivalente?","option_a":"Porque somente o sofrimento físico cria a inteligência no Espírito.","option_b":"Porque Deus sente prazer em vingar-se das criaturas que erraram.","option_c":"Porque cada Espírito é solidário com o seu próprio passado, e a expiação ensina pela experiência da dor aquilo que ele fez outros sofrerem.","option_d":"Porque os Espíritos Superiores cobram tributos proporcionais a cada erro.","option_e":"Porque o arrependimento sincero não tem nenhum valor perante as leis morais.","correct_option":"C","explanation":"Quem abusou da riqueza, do poder ou da saúde aprende, passando pelas provas contrárias, a corrigir o orgulho e a desenvolver a humildade e a caridade.","reference":"O Que é o Espiritismo - Cap. III, itens 146 a 148","difficulty":"dificil","active":true},{"code":849,"book":"o_que_e_espiritismo","statement":"De acordo com o Capítulo III ('Loucura, idiotia', itens 158 a 162), o Espírito do louco ou do idiota de nascença é uma alma inferior ou privada de inteligência?","option_a":"Perdeu definitivamente a memória e a consciência por toda a eternidade.","option_b":"Sim, é uma alma criada sem o princípio da razão humana.","option_c":"Sim, trata-se do espírito de um animal encarnado por engano em corpo humano.","option_d":"Não; o Espírito em si pode ser inteligente, mas acha-se impedido de manifestar seu pensamento pela imperfeição ou lesão dos órgãos cerebrais que lhe servem de instrumento.","option_e":"Não possui alma própria, vivendo apenas pela vida vegetativa do corpo.","correct_option":"D","explanation":"O cérebro é o instrumento de manifestação do pensamento na vida corpórea: assim como o mais hábil músico não pode tirar sons harmoniosos de um instrumento quebrado, o Espírito fica tolhido por órgãos imperfeitos.","reference":"O Que é o Espiritismo - Cap. III, itens 158 a 162","difficulty":"dificil","active":true},{"code":850,"book":"o_que_e_espiritismo","statement":"Segundo o Capítulo III (itens 160 a 162), com que finalidade moral e educativa um Espírito inteligente pode ser submetido à dura prova da idiotia ou da loucura?","option_a":"Para isentar a família de qualquer dever de caridade e assistência.","option_b":"Por mero acidente biológico sem qualquer relação com a justiça de Deus.","option_c":"Para premiar os Espíritos que já atingiram a santidade suprema.","option_d":"Para demonstrar que a matéria governa soberanamente o destino da alma.","option_e":"Como expiação do abuso que fez de sua inteligência, de seu orgulho ou de suas paixões em existência anterior, sofrendo o constrangimento de não poder exprimir-se.","correct_option":"E","explanation":"No corpo do idiota o Espírito tem consciência interior de sua situação e sofre o constrangimento de não poder comunicar-se, expiando assim o abuso anterior de suas faculdades intelectuais.","reference":"O Que é o Espiritismo - Cap. III, itens 160 a 162","difficulty":"dificil","active":true}]$questions$::jsonb)
    AS q(code int, book text, statement text, option_a text, option_b text, option_c text, option_d text, option_e text, correct_option text, explanation text, reference text, difficulty text, active boolean)
)
INSERT INTO public.questions
  (code, book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
SELECT
  q.code, 'o_que_e_espiritismo', q.statement, q.option_a, q.option_b, q.option_c,
  q.option_d, q.option_e, q.correct_option, q.explanation, q.reference,
  q.difficulty, q.active
FROM incoming q
ON CONFLICT (statement) DO UPDATE SET
  code = EXCLUDED.code,
  book = EXCLUDED.book,
  option_a = EXCLUDED.option_a,
  option_b = EXCLUDED.option_b,
  option_c = EXCLUDED.option_c,
  option_d = EXCLUDED.option_d,
  option_e = EXCLUDED.option_e,
  correct_option = EXCLUDED.correct_option,
  explanation = EXCLUDED.explanation,
  reference = EXCLUDED.reference,
  difficulty = EXCLUDED.difficulty,
  active = EXCLUDED.active;

COMMIT;